import React, { useState } from "react";
import {
  Button, Card, CardHeader, CardBody, FormGroup, Form, Input, Container, Row, Col
} from "reactstrap";
import UserHeader from "components/Headers/UserHeader.js";
import { saveCarbonData } from "firebaseUtils/firebaseUtils"; // Import utility function

const CarbonInputPage = () => {
  const [formData, setFormData] = useState({
    electricityUsage: "",
    naturalGasUsage: "",
    renewableEnergyUsage: "",
    fuelOilUsage: "",
    vehicleMiles: "",
    publicTransport: "",
    airTravel: "",
    shipping: "",
    wasteProduced: "",
    recycling: "",
    composting: "",
    landfill: "",
    waterUsage: "",
    wastewater: "",
    notes: "",
  });

  // Handle input changes
  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.id]: e.target.value });
  };

  // Handle form submit
  const handleSubmit = async (e) => {
    e.preventDefault();
    const response = await saveCarbonData(formData);
    if (response.success) {
      alert("Data submitted successfully! 🎉");
    } else {
      alert("Error: " + response.error);
    }
  };

  return (
    <>
      <UserHeader />
      <Container className="mt--7" fluid>
        <Row>
          <Col xl="12">
            <Card className="bg-secondary shadow">
              <CardHeader className="bg-white border-0">
                <Row className="align-items-center">
                  <Col xs="8">
                    <h3 className="mb-0">Carbon Input Form</h3>
                  </Col>
                  <Col className="text-right" xs="4">
                    <Button color="primary" size="sm" onClick={handleSubmit}>
                      Submit
                    </Button>
                  </Col>
                </Row>
              </CardHeader>
              <CardBody>
                <Form>
                  {/* Energy Usage Section */}
                  <h6 className="heading-small text-muted mb-4">Energy Usage</h6>
                  <div className="pl-lg-4">
                    <Row>
                      <Col lg="6">
                        <FormGroup>
                          <label htmlFor="electricityUsage" className="form-control-label">
                            Electricity Usage (kWh)
                          </label>
                          <Input
                            id="electricityUsage"
                            type="number"
                            value={formData.electricityUsage}
                            onChange={handleChange}
                            placeholder="Enter electricity usage in kWh"
                          />
                        </FormGroup>
                      </Col>
                      <Col lg="6">
                        <FormGroup>
                          <label htmlFor="naturalGasUsage" className="form-control-label">
                            Natural Gas Usage (therms)
                          </label>
                          <Input
                            id="naturalGasUsage"
                            type="number"
                            value={formData.naturalGasUsage}
                            onChange={handleChange}
                            placeholder="Enter natural gas usage in therms"
                          />
                        </FormGroup>
                      </Col>
                    </Row>
                  </div>

                  <hr className="my-4" />

                  {/* More sections for Transportation, Waste Management, Water Usage, etc. */}

                </Form>
              </CardBody>
            </Card>
          </Col>
        </Row>
      </Container>
    </>
  );
};

export default CarbonInputPage;
